/* @autogenerated */
package net.civeira.phylax.feature.observe.metric;

import java.util.Iterator;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Edges of the service map from the spans: a CLIENT span whose SERVER child comes from another
 * source is an edge between both sources; a CLIENT span to a database, a queue or a host that is
 * not observed is an edge to an external node. The edges are counted as RED points of method CLIENT
 * of the calling source, with the target as route ({@code → target}), so they share the store and
 * the queries of the metrics.
 *
 * <p>
 * The parent and the child may arrive in different batches (the front and the back are far): the
 * CLIENT spans wait up to two minutes for their child, then they are counted against their external
 * target (or dropped if they have none).
 */
public class EdgeDeriver {

  public static final String ARROW = "→ ";
  private static final long WAIT_MILLIS = 120_000;
  private static final int MAX_PENDING = 50_000;

  /** A CLIENT span waiting for its SERVER child. */
  record Pending(String src, long start, double millis, boolean error, String external,
      long arrived) {}

  private final MetricDeriver deriver;
  private final Map<String, Pending> pending = new ConcurrentHashMap<>();

  public EdgeDeriver(final MetricDeriver deriver) {
    this.deriver = deriver;
  }

  /**
   * A CLIENT (or PRODUCER) span of a source.
   *
   * @param database {@code db.system} (+ name): the edge is known now, there is no child
   * @param external host, peer service or messaging system when the child never arrives
   */
  public void client(final String src, final String spanId, final long start, final double millis,
      final boolean error, final String database, final String external, final long now) {
    if (null != database) {
      edge(src, database, start, millis, error);
    } else if (null != spanId && pending.size() < MAX_PENDING) {
      pending.put(spanId, new Pending(src, start, millis, error, external, now));
    }
  }

  /** A SERVER span: if its parent is a pending CLIENT span of another source, that is the edge. */
  public void server(final String src, final String parentId) {
    if (null == parentId || parentId.isEmpty()) {
      return;
    }
    Pending parent = pending.remove(parentId);
    if (null != parent && !parent.src().equals(src)) {
      edge(parent.src(), src, parent.start(), parent.millis(), parent.error());
    } else if (null != parent) {
      // A call inside the same source is not an edge of the map
      return;
    }
  }

  /** Every minute: the CLIENT spans that waited too long go to their external target. */
  public void sweep(final long now) {
    for (Iterator<Map.Entry<String, Pending>> it = pending.entrySet().iterator(); it.hasNext();) {
      Pending item = it.next().getValue();
      if (now - item.arrived() > WAIT_MILLIS) {
        it.remove();
        if (null != item.external()) {
          edge(item.src(), item.external(), item.start(), item.millis(), item.error());
        }
      }
    }
  }

  int pending() {
    return pending.size();
  }

  private void edge(final String from, final String to, final long start, final double millis,
      final boolean error) {
    deriver.record(from, ARROW + to, MetricDeriver.CLIENT, start, millis, error);
  }
}
